#!/usr/bin/env bash
# Runtime library gate: Sabiko.Runtime.dll must be built, and the committed IL probes under
# runtime/tests must assemble, verify clean and behave like the rustc-compiled reference:
#   format.il prints exactly format.expected (generated by rustc, see the file header);
#   panic.il exits with 101 and reports the panic, with its location, on stderr;
#   checks.il fails a run-time check through a Checks throw helper: exit 101, Rust's report.
# Requires scripts/setup-dotnet.sh (which builds the runtime) or scripts/build-runtime.sh.
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
[[ -f "$ROOT/tools/env.sh" ]] && source "$ROOT/tools/env.sh"
runtime="${SABIKO_RUNTIME_DIR:-$ROOT/tools/runtime}/Sabiko.Runtime.dll"
[[ -f "$runtime" ]] || { echo "runtime: $runtime missing; run scripts/build-runtime.sh" >&2; exit 1; }

status=0
actual="$("$ROOT/scripts/il-run.sh" "$ROOT/runtime/tests/format.il")"
if diff <(printf '%s\n' "$actual") "$ROOT/runtime/tests/format.expected"; then
  echo "runtime format: ok"
else
  echo "runtime format: output mismatch" >&2; status=1
fi

mkdir -p "$ROOT/target/il/panic"
stderr_file="$ROOT/target/il/panic/stderr.txt"
code=0
"$ROOT/scripts/il-run.sh" "$ROOT/runtime/tests/panic.il" >"$ROOT/target/il/panic/stdout.txt" 2>"$stderr_file" || code=$?
if [[ $code == 101 ]] && [[ "$(tail -n 2 "$stderr_file")" == "thread 'main' panicked at src/probe.sabi:7:5:"$'\n'"boom" ]] \
   && [[ "$(cat "$ROOT/target/il/panic/stdout.txt")" == "before" ]]; then
  echo "runtime panic: ok"
else
  echo "runtime panic: expected exit 101 with the located 'boom' report on stderr, got exit $code:" >&2
  cat "$stderr_file" >&2; status=1
fi
stderr_file="$ROOT/target/il/checks/stderr.txt"
mkdir -p "$ROOT/target/il/checks"
code=0
"$ROOT/scripts/il-run.sh" "$ROOT/runtime/tests/checks.il" >"$ROOT/target/il/checks/stdout.txt" 2>"$stderr_file" || code=$?
if [[ $code == 101 ]] && [[ "$(tail -n 2 "$stderr_file")" == "thread 'main' panicked at src/probe.sabi:3:9:"$'\n'"attempt to add with overflow" ]] \
   && [[ "$(cat "$ROOT/target/il/checks/stdout.txt")" == "3" ]]; then
  echo "runtime checks: ok"
else
  echo "runtime checks: expected exit 101 with the located overflow report on stderr, got exit $code:" >&2
  cat "$stderr_file" >&2; status=1
fi
exit $status
